create or replace function public.settle_card_bill(p_card_id uuid,p_statement_month date,p_paid_on date default current_date) returns bigint language plpgsql security invoker set search_path='' as $$declare uid uuid:=auth.uid();total bigint;month_start date:=date_trunc('month',p_statement_month)::date;begin if uid is null then raise exception 'not authenticated';end if;if not exists(select 1 from public.credit_cards c where c.id=p_card_id and c.user_id=uid) then raise exception 'invalid card';end if;select coalesce(sum(i.amount_minor),0) into total from public.card_installments i join public.card_purchases p on p.id=i.purchase_id where i.user_id=uid and p.card_id=p_card_id and i.billing_month=month_start and i.paid_at is null;if total<=0 then return 0;end if;insert into public.card_bill_payments(user_id,card_id,statement_month,amount_minor,paid_on) values(uid,p_card_id,month_start,total,p_paid_on) on conflict(card_id,statement_month) do update set amount_minor=excluded.amount_minor,paid_on=excluded.paid_on;update public.card_installments i set paid_at=now() from public.card_purchases p where i.purchase_id=p.id and i.user_id=uid and p.card_id=p_card_id and i.billing_month=month_start and i.paid_at is null;return total;end;$$;
